INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Adventure Escape: Allied Spies', 'Newlyweds Ed and Marie Hamilton parachute into Occupied France on a mission to smuggle two scientists out of Europe. They meet the French Resistance but things quickly go wrong as ruthless Major Kressler smashes their network. Who’s the traitor? Where are the scientists? What mega-weapon is Major Kressler preparing? Will Ed and Marie ever get a night alone?' FROM games WHERE igdb_id = 123435 ON CONFLICT (game_id, language_code) DO NOTHING;
