INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Myths of the World: The Black Sun', 'In a small town tucked away in the Swiss Alps, the newly appointed commander clashes with the basilisk -- a mythical creature with the power to petrify people. At first glance, it looks like the beast is running wild, spreading terror around the small Swiss town, but, as the beast hunt continues, it appears that the basilisks victims are not random. Could the unveiling of unsettling truths reveal the true nature of the beast?' FROM games WHERE igdb_id = 74308 ON CONFLICT (game_id, language_code) DO NOTHING;
