INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guardians of the Galaxy Pinball', 'Marvel’s Guardians of the Galaxy: The Telltale Series delivers a brand new story of the universe’s unlikeliest heroes, the rag-tag band of outlaws who go by the names Star-Lord, Gamora, Drax, Rocket, and Groot. In the wake of an epic battle, the Guardians discover an artifact of unspeakable power. Each of the Guardians has a reason to desire this relic, as does a ruthless enemy who is the last of her kind, and who will stop at nothing to tear it from their hands.' FROM games WHERE igdb_id = 83706 ON CONFLICT (game_id, language_code) DO NOTHING;
