INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mirrors', 'Mirrors is a strategy puzzle game where you play as an adventurer navigating your way through the tombs of ancient Egypt. By using the power of the sun you must direct light by reflecting it off various mirrors onto an orb which will activate the door into the next tomb. While doing this you must deal with a range of obstacles and traps that are in place to hinder your progress and keep you from reaching the Pharaohs treasure.' FROM games WHERE igdb_id = 69387 ON CONFLICT (game_id, language_code) DO NOTHING;
