INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Poker World', 'Poker World is brought to you by the makers of Governor of Poker. In this great offline poker game, you''re battling and bluffing your way through several continents and famous poker cities. Ever played poker in Macau? Or visited the majestic Monaco casino? Or went all in in the Bellagio in Las Vegas? This is your chance. And you''ll play poker with only one goal: to become the best poker player in the world.' FROM games WHERE igdb_id = 55683 ON CONFLICT (game_id, language_code) DO NOTHING;
