INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spaceship Trucker', 'Spaceship Trucker is a 2D shooter. You are a spaceship trucker travelling down the dangerous star route. The Flees will try to block your way through space and pirates want to steal your precious cargo. Watch out for meteors as well. In each level you''ll have to prove yourself worthy of being a spaceship trucker by fighting off dangerous boss enemies.' FROM games WHERE igdb_id = 55576 ON CONFLICT (game_id, language_code) DO NOTHING;
