INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ping Pong Trick Shot 2', 'Use the Circle Pad or Stylus to throw a ball at just the right trajectory and power to make it land inside the cup. The sequel introduces new challenging technical levels, improved ball physics and futuristic cyber graphics. Four game modes are included. Score Attack Mode Throw the ball into the cup as many times as possible with 20 throws. Mission Mode Throw the ball into the cup as many times as possible on five random levels with a specific number of bounces. Challenge Mode Challenge yourself to complete all stages with 35 throws. Time Attack Mode Throw the ball into the cup as many times as possible in 60 seconds.' FROM games WHERE igdb_id = 84823 ON CONFLICT (game_id, language_code) DO NOTHING;
