INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Go Up Goat', '"Go Up Goat" is an endless level platformer. The player needs to help a crazy goat to collect coins to open a gate to the next level. There is a special thing about the goat - it can''t stop running and will fall down without your help. All levels are generated - theoretically you can play forever. Higher level will become more difficult and will be more complex then the levels before.' FROM games WHERE igdb_id = 28959 ON CONFLICT (game_id, language_code) DO NOTHING;
