INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Megacity Builder', 'A city builder that has all the bells and whistles you know and love with one twist. In Megacity Builder you build a whole nation not just a city. Pass laws at the national level. Fiddle with the budgets at the city level. Build cities like in classic city builders while producing resources to feed your massive capital. Massive game world to keep you busy building for many hours.' FROM games WHERE igdb_id = 44164 ON CONFLICT (game_id, language_code) DO NOTHING;
