INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('flub-fighter', 31218, '2017-02-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2bf2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/djeddpgx0lag8irpstli.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flub Fighter', 'Flub Fighter is a Free to Play 3-D, action-party game where up to four players fight against each other for flubby dominance. Flubs cannot be harmed through punching alone; only a well-placed trap or punch that send a Flub flying into dangerously placed lethal hazards can score kills. Players can utilize a one-button, multi-directional punch system to knock opponents back and to maneuver around levels. Tapping the button delivers a short-ranged, light punch. Holding down the button charges up your Flub and allows for a powerful punch that sends you and your opponent flying. In addition to punching, players can collect items during a match to hinder opponents. Items can be thrown directly at opponents, or be placed on the environment as traps. To achieve victory, players will need to outsmart opponents and stay on their toes in the face of dangerous, hazard-filled environments.' FROM games WHERE igdb_id = 31218 ON CONFLICT (game_id, language_code) DO NOTHING;
