INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Streets of Rage Zombies', 'It''s Streets of Rage with zombies! This bloody beat ''em up was created as an OpenBOR project and released in 2017 on ChronoCrash.com. Play as one of six Streets of Rage fighters, including a zombie, and smash your way through hordes of disgustingly awesome mutilated corpses of the undead. With great sprite-based graphics and fast and fluid brawler gameplay, creator suhmai adds a worthy entry into the homebrew OpenBOR database.' FROM games WHERE igdb_id = 272336 ON CONFLICT (game_id, language_code) DO NOTHING;
