INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hard Rock Zombie Truck', 'Nothing complicated. All you have to do is to drive, burn up, knock down, shoot and blast zombies and monsters. And don''t forget to have fun, of course! This light and a bit crazy 2D zombie shooter gives you a chance to have a pleasant truck journey along the world after zombie-apocalypse.' FROM games WHERE igdb_id = 54337 ON CONFLICT (game_id, language_code) DO NOTHING;
