INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TankCraft', 'TankCraft is an action game based around gladiatorial style tank battles, but skill alone won''t be enough to succeed here, the unique thing about TankCraft is the player crafts their own tanks however they choose with no restrictions to shapes, sizes or design. Battles are split into 6 weight categories; Feather, Light, Medium, Heavy, Super Heavy and Titan(Unlimited) and any tank under the weight limit for that class can compete.' FROM games WHERE igdb_id = 31193 ON CONFLICT (game_id, language_code) DO NOTHING;
