INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chris and the Badgers', 'In Chris and the Badgers, the player controls Chris on his mission to catch as many badgers as possible. This 80s arcade inspired game is played with two buttons, one to swing the net to catch badgers and the other to jump over danger. The game ends when Chris comes in contact with a badger or a mole, or if he swings his net over the buzzard which flies by. The game includes an online leaderboard for players to share their high scores.' FROM games WHERE igdb_id = 61592 ON CONFLICT (game_id, language_code) DO NOTHING;
