INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rabbids Crazy Rush', 'How will the Rabbids fulfill their borderline-insane idea this time? By collecting pepper cans that will provide the gas to power their moon-bound balloon. It''s a crazy idea, but it just might work! With the assistance of myriad powers and abilities, you''ll guide your Rabbids around the world in their quest to make their idea come to life.' FROM games WHERE igdb_id = 90356 ON CONFLICT (game_id, language_code) DO NOTHING;
