INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NOBUNAGA''S AMBITION: Sengoku Gunyuuden', '"Nobunaga''s Ambition: Sengoku Gun''yuden" is the third in the series and was released in Japan in 1988 and later in the US as "Nobunaga''s Ambition II." In this simulation game, players take on the role of a Daimyo of the Warring States period, attract followers, and use strategy and tactics to gain control of the 38 domains of Japan.' FROM games WHERE igdb_id = 90573 ON CONFLICT (game_id, language_code) DO NOTHING;
