INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Zelda: Breath of the Wild - Limited Edition', 'Forget everything you know about The Legend of Zelda games. Step into a world of discovery, exploration and adventure in The Legend of Zelda: Breath of the Wild, a boundary-breaking game in the acclaimed series. The limited edition contains the game (Nintendo Switch version), The Legend of Zelda: Breath of the Wild Sound Selection CD and a Master Sword of Resurrection figurine.' FROM games WHERE igdb_id = 50598 ON CONFLICT (game_id, language_code) DO NOTHING;
