INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'You Must be 18 or Older to Enter', 'It''s the 1990s. You''re alone at home, and you heard about this thing called porn at school. You Must be 18 or Older to Enter blurs several genres together to create an anxious horror experience, one that hits a little too close. How deep will you dive before your parents come home? Do you even like this stuff?' FROM games WHERE igdb_id = 68466 ON CONFLICT (game_id, language_code) DO NOTHING;
