INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fear For Sale: The Curse of Whitefall Collector''s Edition', 'Paranormal occurrences are spooking the workers and halting construction at a hotel site in Alaska, so you’re sent to investigate. Things quickly turn dark as apparitions try to keep you away and you’re transported into the past! Nothing is as it seems in this old mining town. Can you keep history from repeating itself and save yourself in time? Find out in this haunting hidden-object puzzle adventure!' FROM games WHERE igdb_id = 283520 ON CONFLICT (game_id, language_code) DO NOTHING;
