INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mobo Greenhouse Garden', 'Mobo Greenhouse is a gardening simulation game designed for children. Players plant seeds, grow vegetables and flowers, and can receive in-game awards for their progress. Certain plants attract bees that produce honey, which can be enjoyed by various animal characters. The game includes features such as watering, weeding, and taking care of seeds. It aims to demonstrate cause-and-effect, stimulate memory, and support hand–eye coordination in a kid-friendly environment.' FROM games WHERE igdb_id = 256903 ON CONFLICT (game_id, language_code) DO NOTHING;
