INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Homelesshood', 'You are homeless person at post apocalyptic Earth. Use cans, bottles and other weapons to kill homeless people who are stopping you during your travel to the last bridge on Earth. But be careful, you are not the only one who can throw!' FROM games WHERE igdb_id = 55384 ON CONFLICT (game_id, language_code) DO NOTHING;
