INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('luftrauserz', 196370, '2017-12-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5mw7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1k53.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LuftrauserZ', 'LuftrauserZ is an official Commodore demake of the 2014 game Luftrausers with gameplay and features similar to the original game. It is a 2D air combat game played from a side view where the plane can fly in any direction using rotation as the screen scrolls along. Control of the plane is often based on short bursts of thrusts and it can only shoot in the direction it is facing with an unlimited number of bullets. The game consists of several levels that are won by achieving one of three win conditions, for instance killing a certain number of fighters, boats, general enemies or reaching a certain score. Combat encourages risks to build up combos. Health is represented through the border surrounding the game''s screen. When it is black the plane is in good health, but when the plane is hit the border flashes, turns red and the colour then changes back to black gradually. When hit with a red border already present the plane blows up.
