INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SkidStorm', 'SkidStorm is a free worldwide multiplayer realtime racing game, and has simple graphics. You can challenge others online or play offline online. It offers the smooth operation that is very easy to master! In the game you can control the cars, wander all kinds of tracks and sweep your fingers to experience the exciting races. You can also fill nitro tanks to accelerate or catch up to become the champion.' FROM games WHERE igdb_id = 54977 ON CONFLICT (game_id, language_code) DO NOTHING;
