INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anomie', 'Anomie is set in a fictional world that resembles our modern day. The protagonist, Quentin, finds himself experiencing a chain of events that leads him to what can only be described as a new life. A new place with new rules—a new life, a new future. Will the public authority''s desperate efforts bear fruit?' FROM games WHERE igdb_id = 55548 ON CONFLICT (game_id, language_code) DO NOTHING;
