INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Devwill', 'Devwill is a platform game with arcade graphics and gameplay. All visuals are almost in black and white, with some details showing some color saturation. The most important aesthetic feature is the "old black and white movies" effects, such as screen scratches, old projector sounds, and intertitles texts showing dialogs and narratives. Expect a challenging game with a mysterious and reflexive yet poetic background story.' FROM games WHERE igdb_id = 74133 ON CONFLICT (game_id, language_code) DO NOTHING;
