INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ringognir 2', 'Ringognir 2 is a nice little puzzle game that could cost you a lot of your time and nerves. Your goal is to build spheres with rings and match the line of the same color. As you progress your levels get harder and harder and new colors come into play.' FROM games WHERE igdb_id = 63737 ON CONFLICT (game_id, language_code) DO NOTHING;
