INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deer Simulator', 'Cruise the woods in search of skittish does or patrol for trespassing bucks. Beware, hunters and coyotes are waiting for the opportunity to end your quest for huge antlers. Experience the first of it''s kind role reversal hunting game! Start off as a spike buck then fight, breed and survive your way to becoming a huge monster buck with massive antlers! Complete with realistic wildlife behavior and environments, with changing weather conditions.' FROM games WHERE igdb_id = 83185 ON CONFLICT (game_id, language_code) DO NOTHING;
