INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Island Tribe 4', 'Help the once-evil shaman find his true way in Island Tribe 4, a delightful new adventure from the hit series. The islanders are finally happy once again. They are back on their island, saved the Chief''s stolen bride, and celebrated the magnificent wedding. Even the evil shaman is now their friend. Because of this, they have agreed to help him return to who he once was.' FROM games WHERE igdb_id = 76635 ON CONFLICT (game_id, language_code) DO NOTHING;
