INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Korunu Kopia: Fushigi no Sumu Machi', 'A visual novel by Amateru and Sous le Pawlowina. Kouta is in a train station in France when he sees Rin, a ditsy kirin, and her brother Hati, a fenrir. Rin then eats her train ticket. All three are headed to Cornu Copia, the city where miraculous creatures live. The game is playable in Chinese and Japanese.' FROM games WHERE igdb_id = 135895 ON CONFLICT (game_id, language_code) DO NOTHING;
