INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stream Avatars', 'Stream Avatars is a program enabling viewers in your twitch stream to be represented with avatars and gear that you import to the software. The user/streamer can choose who gets to show up, whether it''s all viewers, your followers, subscribers, or just individuals with special privileges that you set.' FROM games WHERE igdb_id = 52432 ON CONFLICT (game_id, language_code) DO NOTHING;
