INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hidden Expedition: The Pearl of Discord', 'The H.E.L.P agency has requested your assistance with recovering a stolen treasure that once belonged to the great Marco Polo. In 1324, he gifted a powerful pearl to his friend, Peter Tayal, who promised to pass it down through his family to keep the Zambetti Family from acquiring it. Venture around the world as you search for colorful hidden objects and unravel exciting puzzles to collect clues! Also, travel to Venice in the daring bonus chapter to save the city from an incoming tide! Can you follow the trail and expose the thief in this exhilarating Hidden Object adventure?' FROM games WHERE igdb_id = 140037 ON CONFLICT (game_id, language_code) DO NOTHING;
