INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Remoove', 'Remoove is a puzzle game in which a player needs to remove objects from their original positions and move them in a way they collect all the stars in every level. But there''s a catch - once you pick up an object, you need to move it constantly because if you stop the object will drop and fall and therefore your level progress will be lost.' FROM games WHERE igdb_id = 67909 ON CONFLICT (game_id, language_code) DO NOTHING;
