INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Western FPS', 'Western FPS is old-school 3D FPS, that looks and plays like the first games in this genre, that were developed in 90s. Game is based on Ray Casting technology, but it has prettier cartoon-like graphics. Western FPS includes interesting storyline, that tells you a story about Alan Wilborn. You will fight against different types of enemies, solve problems of civilians and explore colorful world, filled with secrets and easter eggs.' FROM games WHERE igdb_id = 29245 ON CONFLICT (game_id, language_code) DO NOTHING;
