INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Summer Lesson: Miyamoto Hikari Edition', 'Get ready to play what we all really bought the Playstation VR for: Summer Lesson: Hikari Miyamoto - available exclusively in Asia! Not only is the much anticipated English version available on the PSN, but Namco Bandai have gone the extra mile and added a fully complete physical release, which includes four different DLC codes! April 27 will mark the beginning of your lesson, and having a timeless piece of memorabilia for one of the first true virtual experiences is priceless!' FROM games WHERE igdb_id = 166248 ON CONFLICT (game_id, language_code) DO NOTHING;
