INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hunger', 'Hunger in Los Angeles is an immersive journalistic experience set in the heart of the city, where the indigent are trying to survive on an over-strained food distribution system. By embedding audio that was captured from the First Unitarian Church in an immersive 3D Unity scene, we become witness to a distressing event that unfolds.' FROM games WHERE igdb_id = 168530 ON CONFLICT (game_id, language_code) DO NOTHING;
