INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Raccoon Hero: Starlight', 'Your goal in this game is to help the raccoon cubs escape their ball cages by matching their color with the color of the ball you throw at it. The babies are hidden among hundreds of other colorful balls. So basically, you need to destroy as much balls as necessary and achieve the certain score that is calculated for every level.' FROM games WHERE igdb_id = 54480 ON CONFLICT (game_id, language_code) DO NOTHING;
